package com.company.tpm.dashboard;import com.company.tpm.employee.*;import com.company.tpm.training.*;import com.company.tpm.schedule.*;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DashboardService{private final EmployeeRepository employees;private final TrainingCourseRepository courses;private final TrainingSessionRepository sessions;public DashboardService(EmployeeRepository e,TrainingCourseRepository c,TrainingSessionRepository s){employees=e;courses=c;sessions=s;}public record Summary(long activeEmployees,long activeCourses,long upcomingSessions){}@Transactional(readOnly=true)public Summary summary(){return new Summary(employees.countByStatus(Employee.Status.ACTIVE),courses.countByActiveTrue(),sessions.countScheduledOn(LocalDate.now().plusDays(1)));}}
